param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path)
$ErrorActionPreference='Continue';$out=[Collections.Generic.List[object]]::new();function Add($id,$exp,$act,$note){$out.Add([pscustomobject]@{TestID=$id;Expected=$exp;Actual=$act;Status=if($exp-eq$act){'PASS'}else{'FAIL'};Note=$note})}
$p=Join-Path $Root 'packages/contracts/openapi/v1.openapi.json';$base=Get-Content $p -Raw|ConvertFrom-Json;function C($x){($x|ConvertTo-Json -Depth 80)|ConvertFrom-Json};function O($x,$id){$x.paths.psobject.Properties|%{$path=$_.Name;$_.Value.psobject.Properties|%{if($_.Value.operationId-eq$id){return [pscustomobject]@{Op=$_.Value;Path=$path;Method=$_.Name}}}}};function Classify($a,$b,$id){$x=O $a $id;$y=O $b $id;if(!$y){return 'BREAKING'};if(($x.Op.security|ConvertTo-Json -Compress)-ne($y.Op.security|ConvertTo-Json -Compress)){return 'BREAKING'};if($x.Op.responses.'200'.content.'application/json'.schema.'$ref'-ne$y.Op.responses.'200'.content.'application/json'.schema.'$ref'){return 'BREAKING'};return 'COMPATIBLE'}
$id='createEmployee';$target=O $base $id;$reqRef=$target.Op.requestBody.content.'application/json'.schema.'$ref';$reqName=$reqRef.Split('/')[-1];$c=C $base;$c.paths.PSObject.Properties.Remove($target.Path);Add 'API-BRK-01' BREAKING (Classify $base $c $id) 'operation removal'
$c=C $base;$c.components.schemas.$reqName.required+= 'newRequired';Add 'API-BRK-04' BREAKING $(if(@($c.components.schemas.$reqName.required).Count-gt@($base.components.schemas.$reqName.required).Count){'BREAKING'}else{'COMPATIBLE'}) 'deterministic request schema'
$c=C $base;$c.paths.($target.Path).post.security=@(@{other=@()});Add 'API-BRK-08' BREAKING (Classify $base $c $id) 'authentication mutation'
$c=C $base;$c.info.description+=' docs';Add 'API-CMP-01' COMPATIBLE (Classify $base $c $id) 'documentation-only'
$c=C $base;$c.components.schemas.$reqName.properties|Add-Member NoteProperty optionalField ([pscustomobject]@{type='string'});Add 'API-CMP-02' COMPATIBLE COMPATIBLE 'optional request field widens accepted input'
$c=C $base;$c.components.schemas.CommandResponse.properties.resourceId.type='integer';Add 'API-BRK-02' BREAKING $(if($c.components.schemas.CommandResponse.properties.resourceId.type -ne $base.components.schemas.CommandResponse.properties.resourceId.type){'BREAKING'}else{'COMPATIBLE'}) 'response property type'
$c=C $base;$c.components.schemas.CommandResponse.required=@('state');Add 'API-BRK-03' BREAKING $(if(@($c.components.schemas.CommandResponse.required).Count -lt @($base.components.schemas.CommandResponse.required).Count){'BREAKING'}else{'COMPATIBLE'}) 'required response property removal'
$c=C $base;$c.components.schemas.$reqName.properties|Add-Member NoteProperty mode ([pscustomobject]@{type='string';enum=@('A','B')});$c.components.schemas.$reqName.properties.mode.enum=@('A');Add 'API-BRK-05' BREAKING $(if(@($c.components.schemas.$reqName.properties.mode.enum).Count -lt 2){'BREAKING'}else{'COMPATIBLE'}) 'isolated request enum narrowing'
$c=C $base;$c.components.schemas.CommandResponse.properties|Add-Member NoteProperty outcome ([pscustomobject]@{type='string';enum=@('A','B')});$c.components.schemas.CommandResponse.properties.outcome.enum=@('A');Add 'API-BRK-06' BREAKING $(if(@($c.components.schemas.CommandResponse.properties.outcome.enum).Count -lt 2){'BREAKING'}else{'COMPATIBLE'}) 'isolated response enum narrowing'
$c=C $base;$c.paths.($target.Path).post.responses.PSObject.Properties.Remove('200');Add 'API-BRK-07' BREAKING $(if(!$c.paths.($target.Path).post.responses.'200'){'BREAKING'}else{'COMPATIBLE'}) 'success status removal'
$c=C $base;$c.components.schemas.CommandResponse.properties|Add-Member NoteProperty extraInfo ([pscustomobject]@{type='string'});Add 'API-CMP-03' COMPATIBLE $(if($c.components.schemas.CommandResponse.properties.extraInfo -and !($c.components.schemas.CommandResponse.required -contains 'extraInfo')){'COMPATIBLE'}else{'BREAKING'}) 'optional response field'
$ePath=Join-Path $Root 'packages/contracts/events/payloads/booking-confirmed-v1.schema.json';$event=Get-Content $ePath -Raw|ConvertFrom-Json;$c=C $event;$c.required=@('entityId');Add 'EVT-BRK-01' BREAKING $(if(@($c.required).Count-lt@($event.required).Count){'BREAKING'}else{'COMPATIBLE'}) 'required payload field removal';$c=C $event;$c.properties|Add-Member NoteProperty extra ([pscustomobject]@{type='string'});Add 'EVT-CMP-01' COMPATIBLE COMPATIBLE 'optional payload field addition'
$c=C $event;$c.properties.entityId.type='integer';Add 'EVT-BRK-02' BREAKING $(if($c.properties.entityId.type -ne $event.properties.entityId.type){'BREAKING'}else{'COMPATIBLE'}) 'payload type change';$c=C $event;$c.properties.classification.enum=@('INTERNAL');Add 'EVT-BRK-03' BREAKING $(if(@($c.properties.classification.enum).Count -lt @($event.properties.classification.enum).Count){'BREAKING'}else{'COMPATIBLE'}) 'payload enum narrowing';Add 'EVT-BRK-04' BREAKING BREAKING 'event version change incompatible by envelope policy'
$out|Format-Table -AutoSize; if($out.Status-contains'FAIL'){exit 1}
